class TFMConditionConnectionNode
{
    List            tolinks, fromLinks;
    str             data;

}

Method.Source:
public str parmData(str _data = data)
{
    data = _data;
    return data;
}

public List getToLinks()
{
    if (tolinks == null)
    {
        tolinks = new List(Types::Class);
    }
    return tolinks;
}

public void addToLink(Object _node)
{
    if (tolinks == null)
    {
        tolinks = new List(Types::Class);
    }
    tolinks.addEnd(_node);
    _node.addFromLink(this);
}

public List getFromLinks()
{
    if (fromLinks == null)
    {
        fromLinks = new List(Types::Class);
    }
    return fromLinks;
}

protected void addFromLink(Object _node)
{
    if (fromLinks == null)
    {
        fromLinks = new List(Types::Class);
    }
    fromLinks.addEnd(_node);
}

public void findStartingNodes(List _startingNodes)
{
    ListEnumerator          lEnum;
    TFMBlockConnectionNode  node;
    if (!fromLinks || !fromLinks.elements())
    {
        _startingNodes.addEnd(this);
    }
    else
    {
        lEnum = fromLinks.getEnumerator();
        while (lEnum.moveNext())
        {
            node = lEnum.Current();
            node.findStartingNodes(_startingNodes);
        }
    }
}

public boolean hasCycle()
{
    Set setVisited = new Set(Types::Class);
    Set setStack = new Set(Types::Class);
    return this.dfs(setVisited, setStack);
}

private boolean dfs(Set _setVisited, Set _setStack)
{
    ListEnumerator          lEnum = tolinks.getEnumerator();
    TFMConditionConnectionNode  node;
    _setVisited.add(this);
    _setStack.add(this);

    while (lEnum.moveNext())
    {
        node = lEnum.Current();
        if (!_setVisited.in(node))
        {
            if (node.dfs(_setVisited, _setStack))
                return true;
        }
        else if (_setStack.in(node))
        {
            return true;
        }
    }

    _setStack.remove(this);
    return false;
}
